-- Migration 024: soccer club stints confirmed by the player's Wikipedia infobox (senior career)
-- Run in Supabase SQL Editor. One transaction. PURE ASCII (no player names in this file: names come from players).
-- Approved 12 Oct 2026 (review page "Club Stints Review"): for players who own soccer facts, add played_for_team
-- facts at our 96 clubs when the infobox's SENIOR career lists that club (linked to the club's article, not a
-- B / II / reserve side) with league appearances (or no appearance count given). Loans count.
--   4415 rows also in Wikidata (owner_method 'wikipedia infobox + wikidata (024)')
--   510 rows in the infobox only (owner_method 'wikipedia infobox (024)')
--   34 existing unowned rows get their owner; 4891 rows are inserted (3 under the article title,
--   because a namesake already has that club under the plain name).
-- LEFT OUT (user decisions): youth-only, reserve-team, manager-only, not in the infobox, 0 appearances, no infobox.
-- HELD: 294 stints that start in 2026 (need a second independent source first; separate migration).
-- Nothing is deleted. Existing facts the infobox doesn't support are reviewed separately.
-- 0. GUARD (first): stops with a clear message if already applied, or if the data changed since it was prepared.
-- 1. BACKUP: the 34 rows that get an owner, as they are now (RLS on, closed).

BEGIN;

DO $mig$
DECLARE n BIGINT;
BEGIN
  SELECT count(*) INTO n FROM player_facts WHERE owner_method IN ('wikipedia infobox + wikidata (024)', 'wikipedia infobox (024)');
  IF n > 0 OR to_regclass('public.backup_20261012_facts_024') IS NOT NULL THEN
    RAISE EXCEPTION 'Migration 024 is already applied (% rows with its owner_method). Nothing changed.', n;
  END IF;
  SELECT count(*) INTO n FROM player_facts WHERE id IN (804152, 800597, 800757, 804251, 802789, 803275, 800858, 803405, 804804, 801948, 804020, 803396, 803675, 800352, 802093, 809443, 802932, 824292, 784649, 841593, 784636, 782199, 791423, 798621, 777072, 798673, 801790, 802086, 802055, 796437, 804116, 802482, 803222, 836641) AND player_id IS NULL AND sport = 'Soccer' AND fact_type = 'played_for_team';
  IF n <> 34 THEN RAISE EXCEPTION '024 guard: expected 34 unowned rows to own, found %. Nothing changed.', n; END IF;
END $mig$;

-- --- 1. BACKUP ------------------------------------------------------------------------------------
CREATE TABLE backup_20261012_facts_024 AS SELECT * FROM player_facts WHERE id IN (804152, 800597, 800757, 804251, 802789, 803275, 800858, 803405, 804804, 801948, 804020, 803396, 803675, 800352, 802093, 809443, 802932, 824292, 784649, 841593, 784636, 782199, 791423, 798621, 777072, 798673, 801790, 802086, 802055, 796437, 804116, 802482, 803222, 836641);
ALTER TABLE backup_20261012_facts_024 ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON backup_20261012_facts_024 FROM anon, authenticated;

