  (SELECT count(*) FROM player_facts WHERE owner_method = 'wikipedia infobox (024)')                                        AS rows_infobox_only,
  (SELECT count(*) FROM player_facts WHERE owner_method LIKE '%(024)' AND player_id IS NULL)              AS unowned_024,
  (SELECT count(*) FROM (SELECT player_id, fact_value FROM player_facts WHERE sport = 'Soccer' AND fact_type = 'played_for_team'
     AND player_id IN (SELECT player_id FROM player_facts WHERE owner_method LIKE '%(024)') GROUP BY 1, 2
     HAVING count(*) FILTER (WHERE owner_method LIKE '%(024)') > 0 AND count(*) > 1) d)                  AS doubled_by_024,
  (SELECT string_agg(f.fact_value, ', ' ORDER BY f.fact_value) FROM player_facts f JOIN players p ON p.id = f.player_id
