  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id
     WHERE p.wikipedia_page_id = 55996885 AND f.fact_value = 'Barcelona')       AS gordon_barcelona_held,
  (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relname = 'backup_20261012_facts_024')            AS backup_rls,
  (SELECT count(*) FROM information_schema.role_table_grants
     WHERE table_name = 'backup_20261012_facts_024' AND grantee IN ('anon', 'authenticated'))            AS backup_browser_grants;
